import json

def format_request_log(method: str, path: str, headers: dict, body: str) -> str:
    sensitive_headers = ['Authorization', 'Cookie']
    masked_headers = {k: (v if k not in sensitive_headers else '[REDACTED]') for k, v in headers.items()}
    log_entry = {
        'method': method,
        'path': path,
        'headers': masked_headers,
        'body_preview': body[:50] + '...' if body else ''
    }
    return json.dumps(log_entry)

